import{_ as d,o as r,c as e,a5 as o}from"./chunks/framework.R-FQ1xZ2.js";const p=JSON.parse('{"title":"L2 导览 · 提示工程与结构化输出","description":"","frontmatter":{"title":"L2 导览 · 提示工程与结构化输出","layer":"L2","layerTitle":"L2 · 提示工程与结构化输出","order":0,"points":[],"freq":"高","hours":57,"tags":["index","prompt-engineering","structured-output","context-engineering"]},"headers":[],"relativePath":"kb/l2-prompt/index.md","filePath":"kb/l2-prompt/index.md","lastUpdated":null}'),n={name:"kb/l2-prompt/index.md"};function a(l,t,s,i,c,h){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="l2-导览-·-提示工程与结构化输出" tabindex="-1">L2 导览 · 提示工程与结构化输出 <a class="header-anchor" href="#l2-导览-·-提示工程与结构化输出" aria-label="Permalink to &quot;L2 导览 · 提示工程与结构化输出&quot;">​</a></h1><blockquote><p>本层共 <strong>22 个知识点 / 8 页 / 合计 57 学时</strong>。这是全套知识体系里<strong>最能直接转成简历条目和面试问答</strong>的一层：它不讲模型内部怎么算，讲的是<strong>你怎么把一个概率模型用成一个可靠的系统</strong>。</p></blockquote><h2 id="这一层在解决什么问题" tabindex="-1">这一层在解决什么问题 <a class="header-anchor" href="#这一层在解决什么问题" aria-label="Permalink to &quot;这一层在解决什么问题&quot;">​</a></h2><p>L0 解决「代码写不写得对」，L1 解决「模型的脾气你懂不懂」，<strong>L2 解决的是「你写的这段东西，模型到底听不听得懂、守不守规矩」</strong>。它的所有内容都在回答同一类问题：</p><ul><li>我该怎么组织这次请求？（消息角色、系统提示、模板化）</li><li>我该怎么让模型按我想要的<strong>方式</strong>思考？（示例、CoT、分解、ReAct、Reflection）</li><li>我该怎么让模型的输出<strong>被别人写的程序消费</strong>？（JSON Mode、JSON Schema、Function Calling、校验重试）</li><li>我该怎么证明我的改动<strong>确实变好了</strong>？（版本化、评测闭环）</li><li>我该怎么让它在<strong>长时间、多轮、有外部输入</strong>的情况下不崩、不被骗、还付得起？（上下文工程、注入防护、缓存）</li></ul><p><strong>一句话</strong>：L2 是「把 LLM 从 Demo 做到生产」的那一层。面试官在 AI 岗位面试里问的技术细节，超过一半落在这一层。</p><h2 id="学习顺序与依赖关系" tabindex="-1">学习顺序与依赖关系 <a class="header-anchor" href="#学习顺序与依赖关系" aria-label="Permalink to &quot;学习顺序与依赖关系&quot;">​</a></h2><p>按顺序读，不要跳。每一页都依赖前面几页的概念。</p><table tabindex="0"><thead><tr><th>序</th><th>页面</th><th>覆盖知识点</th><th>学时</th><th>前置依赖</th><th>学完你应该能回答</th></tr></thead><tbody><tr><td>1</td><td><a href="/learn/kb/l2-prompt/01-messages-and-instructions.html">消息角色、系统提示与模板化</a></td><td>L2-01 / 02 / 03</td><td>9</td><td>无（本层起点，建议先读 L1 的 tokenizer 与注意力两页）</td><td>一次请求的每条消息各承担什么职责；为什么规则不能只写在用户消息里</td></tr><tr><td>2</td><td><a href="/learn/kb/l2-prompt/02-few-shot-and-zero-shot.html">Few-shot 示例选择与 Zero-shot 边界</a></td><td>L2-04 / 05</td><td>5</td><td>页面 1</td><td>什么时候该给示例、给几个、按什么标准挑；什么时候给示例反而更差</td></tr><tr><td>3</td><td><a href="/learn/kb/l2-prompt/03-reasoning-patterns.html">推理模式：CoT、Self-Consistency 与任务分解</a></td><td>L2-06 / 07 / 08</td><td>9</td><td>页面 1、2</td><td>CoT 为什么有效（和「模型变聪明了」无关）；Self-Consistency 在什么条件下才有收益</td></tr><tr><td>4</td><td><a href="/learn/kb/l2-prompt/04-react-and-plan.html">ReAct、Plan-and-Solve、Reflection 与 Meta-Prompting</a></td><td>L2-09 / 10 / 11 / 12</td><td>12</td><td>页面 3</td><td>ReAct 的三角色是什么；工具到底是谁在执行；Reflection 什么时候是自欺</td></tr><tr><td>5</td><td><a href="/learn/kb/l2-prompt/05-structured-output.html">JSON Mode、Function Calling 与解析鲁棒性</a></td><td>L2-13 / 14 / 15 / 16</td><td>14</td><td>页面 1、4</td><td>JSON Mode 与 Schema 的强度差在哪；校验的四层各由谁负责；解析失败怎么降级</td></tr><tr><td>6</td><td><a href="/learn/kb/l2-prompt/06-prompt-ops.html">Prompt 版本化、A/B 与评测闭环</a></td><td>L2-17 / 18</td><td>7</td><td>页面 2、3、5（要先有可比较的输出形态）</td><td>你怎么知道改动变好了；为什么一次只能改一个变量；什么叫「不可比」</td></tr><tr><td>7</td><td><a href="/learn/kb/l2-prompt/07-context-engineering.html">上下文工程与压缩摘要</a></td><td>L2-19 / 20</td><td>7</td><td>页面 1、5（结构化输出让摘要可控）</td><td>窗口放不下时先砍谁；哪些信息<strong>不许</strong>被压缩</td></tr><tr><td>8</td><td><a href="/learn/kb/l2-prompt/08-injection-and-cache.html">Prompt 注入、越狱防护与缓存成本</a></td><td>L2-21 / 22</td><td>6</td><td>页面 5、7（要先懂上下文装配才能懂前缀）</td><td>最危险的注入入口是哪个；为什么缓存和注入防护共享同一条顺序纪律</td></tr></tbody></table><p><strong>三条建议的读法</strong>：</p><ol><li><strong>1 → 2 → 3 是概念地基</strong>，这三页不要跳；跳了后面会变成背名词。</li><li><strong>4 和 5 是本层的重心</strong>（合计 26 学时，占本层近一半）。Agent 岗面试几乎必然从这两页里出题。</li><li><strong>6 → 7 → 8 是工程化三页</strong>，可以在第 5 页之后按需先读任意一页——但不要在第 5 页之前读 8，前缀缓存的概念建立在「上下文是一次装配出来的」这个前提上。</li></ol><h2 id="覆盖自检表-l2-01-→-l2-22" tabindex="-1">覆盖自检表（L2-01 → L2-22） <a class="header-anchor" href="#覆盖自检表-l2-01-→-l2-22" aria-label="Permalink to &quot;覆盖自检表（L2-01 → L2-22）&quot;">​</a></h2><p>逐条核对：<strong>22 条全部落在下表中，每条只出现一次</strong>。阅读时可以直接拿它当勾选清单。</p><table tabindex="0"><thead><tr><th>编号</th><th>知识点</th><th>落在哪一页</th><th>完成</th></tr></thead><tbody><tr><td>L2-01</td><td>Messages 角色与对话模板</td><td><code>01-messages-and-instructions.md</code></td><td>☐</td></tr><tr><td>L2-02</td><td>系统提示词设计</td><td><code>01-messages-and-instructions.md</code></td><td>☐</td></tr><tr><td>L2-03</td><td>Prompt 结构模板化</td><td><code>01-messages-and-instructions.md</code></td><td>☐</td></tr><tr><td>L2-04</td><td>Few-shot 与示例选择策略</td><td><code>02-few-shot-and-zero-shot.md</code></td><td>☐</td></tr><tr><td>L2-05</td><td>Zero-shot / Instruction 遵循</td><td><code>02-few-shot-and-zero-shot.md</code></td><td>☐</td></tr><tr><td>L2-06</td><td>Chain-of-Thought（CoT）</td><td><code>03-reasoning-patterns.md</code></td><td>☐</td></tr><tr><td>L2-07</td><td>Self-Consistency</td><td><code>03-reasoning-patterns.md</code></td><td>☐</td></tr><tr><td>L2-08</td><td>任务分解与 Least-to-Most</td><td><code>03-reasoning-patterns.md</code></td><td>☐</td></tr><tr><td>L2-09</td><td>ReAct 提示范式</td><td><code>04-react-and-plan.md</code></td><td>☐</td></tr><tr><td>L2-10</td><td>Plan-and-Solve</td><td><code>04-react-and-plan.md</code></td><td>☐</td></tr><tr><td>L2-11</td><td>Reflection</td><td><code>04-react-and-plan.md</code></td><td>☐</td></tr><tr><td>L2-12</td><td>Meta-Prompting</td><td><code>04-react-and-plan.md</code></td><td>☐</td></tr><tr><td>L2-13</td><td>JSON Mode / JSON Schema</td><td><code>05-structured-output.md</code></td><td>☐</td></tr><tr><td>L2-14</td><td>Function Calling / Tool Schema</td><td><code>05-structured-output.md</code></td><td>☐</td></tr><tr><td>L2-15</td><td>严格模式与校验重试</td><td><code>05-structured-output.md</code></td><td>☐</td></tr><tr><td>L2-16</td><td>解析失败的鲁棒处理</td><td><code>05-structured-output.md</code></td><td>☐</td></tr><tr><td>L2-17</td><td>Prompt 版本化与 A/B</td><td><code>06-prompt-ops.md</code></td><td>☐</td></tr><tr><td>L2-18</td><td>Prompt 评测与优化闭环</td><td><code>06-prompt-ops.md</code></td><td>☐</td></tr><tr><td>L2-19</td><td>上下文工程</td><td><code>07-context-engineering.md</code></td><td>☐</td></tr><tr><td>L2-20</td><td>上下文压缩与摘要</td><td><code>07-context-engineering.md</code></td><td>☐</td></tr><tr><td>L2-21</td><td>Prompt 注入与越狱防护</td><td><code>08-injection-and-cache.md</code></td><td>☐</td></tr><tr><td>L2-22</td><td>Prompt 缓存与成本优化</td><td><code>08-injection-and-cache.md</code></td><td>☐</td></tr></tbody></table><blockquote><p>分布：01 页 3 条｜02 页 2 条｜03 页 3 条｜04 页 4 条｜05 页 4 条｜06 页 2 条｜07 页 2 条｜08 页 2 条 = <strong>22 条，无缺失、无重复</strong>。</p></blockquote><h2 id="必须能画出来的图-白板-口述都能画" tabindex="-1">必须能画出来的图（白板/口述都能画） <a class="header-anchor" href="#必须能画出来的图-白板-口述都能画" aria-label="Permalink to &quot;必须能画出来的图（白板/口述都能画）&quot;">​</a></h2><p>面试里「你画一下」比「你说一下」出现得更多。这五张图必须能徒手画出来并讲清每条箭头的含义：</p><table tabindex="0"><thead><tr><th>#</th><th>图</th><th>要点</th><th>出处</th></tr></thead><tbody><tr><td>1</td><td><strong>ReAct 循环</strong></td><td>Thought → Action → Observation 的三角循环；外部循环边界在哪（哪一步是模型的、哪一步是你的代码）；终止条件</td><td><a href="/learn/kb/l2-prompt/04-react-and-plan.html">04 页</a></td></tr><tr><td>2</td><td><strong>结构化输出「生成 → 校验 → 重试」回环</strong></td><td>容错解析 → 归一化 → 结构校验 → 业务校验 → 回灌报错重试 → 降级；四层各由谁负责</td><td><a href="/learn/kb/l2-prompt/05-structured-output.html">05 页</a></td></tr><tr><td>3</td><td><strong>上下文窗口预算分配</strong></td><td>各段（系统提示 / 工具定义 / 示例 / 摘要 / 检索 / 最近几轮 / 本轮输入）的稳定性与裁剪顺序</td><td><a href="/learn/kb/l2-prompt/07-context-engineering.html">07 页</a></td></tr><tr><td>4</td><td><strong>Prompt 版本化流程</strong></td><td>假设 → 只改一个变量 → 跑评测集 → 与基线比 → 入库/丢弃 → 灰度粘性分流 → 单步回滚</td><td><a href="/learn/kb/l2-prompt/06-prompt-ops.html">06 页</a></td></tr><tr><td>5</td><td><strong>注入攻击面（四个入口）+ 五层防护</strong></td><td>用户输入 / 检索文档 / 工具返回 / 长期记忆 → 隔离包裹 → 独立校验 → 权限门控</td><td><a href="/learn/kb/l2-prompt/08-injection-and-cache.html">08 页</a></td></tr></tbody></table><p>外加两个值得顺手记的：<strong>Function Calling 的五步生命周期</strong>（定义工具 → 模型输出调用意图 → 你的代码执行 → 结果回传 → 再请求）与<strong>前缀缓存的失效条件</strong>（哪个 token 变了，后面全部作废）。可参考 <a href="/learn/diagrams/">/diagrams/</a> 下的 <code>react-loop</code>、<code>function-calling-flow</code>、<code>tool-call-lifecycle</code>、<code>plan-and-execute</code>、<code>yyhelp-specialist-visibility</code>。</p><h2 id="这一层最容易挂在哪" tabindex="-1">这一层最容易挂在哪 <a class="header-anchor" href="#这一层最容易挂在哪" aria-label="Permalink to &quot;这一层最容易挂在哪&quot;">​</a></h2><p>按「挂掉的概率 × 挂掉的代价」排序。前四条是<strong>高危</strong>，最后三条是<strong>加分项没拿到</strong>。</p><ol><li><strong>分不清「哪些保证来自协议、哪些只是请求模型配合」</strong>。把 JSON Mode 当 Schema 用是典型死法：它只保证输出是合法 JSON，<strong>字段名、类型、必填项一概不管</strong>。更隐蔽的是把「严格模式」当成内容正确的保证——它保证结构有效，<strong>不保证事实正确</strong>。一句话答不上来就会被判定为没做过生产系统。</li><li><strong>结构化输出只测了规范路径，并且校验函数是「空输入恒真」的</strong>。<code>check([])</code> 返回 <code>True</code> 这种函数会把「引用全丢光」报告成「校验通过」——<strong>静默假通过比崩溃危险得多</strong>，因为你的验收报告是绿的。正确姿势：归一化必须<strong>上报被丢弃项</strong>，丢弃项非空即判失败；用测试替身往生产校验层喂脏输出。</li><li><strong>说不清 Function Calling 到底谁在执行工具</strong>。模型只输出<strong>意图</strong>（调用哪个工具、什么参数），执行、鉴权、幂等、审计全在你的代码里。这个隔离是你安全性的来源，答成「模型会调用工具」就没了。</li><li><strong>缓存的作用域讲反了</strong>。前缀缓存要求<strong>逐 token 匹配前缀</strong>，所以<strong>任何变的东西都必须靠后</strong>：时间戳、随机 ID、未固定顺序的工具列表、每轮不同的检索结果——它们放在前缀里会让缓存永不命中；而<strong>用户可控的内容更是绝对不能进前缀</strong>（缓存污染）。把「稳定在前、动态在后」讲成「重要的放前面」是没抓住机制。</li><li><strong>A/B 一次改多个变量、分流不粘性、样本不够就说提升</strong>。三条里中任意一条，实验结论就不可信。能主动说出「<strong>这轮样本不足，结论不可比</strong>」，比报一个漂亮的提升数字更能证明你懂实验。</li><li><strong>Reflection 被当成免费的提升手段</strong>。没有外部信号（测试结果、工具返回、schema 报错、明确评分标准）时，让模型检查自己只会得到另一段看起来合理的文本——<strong>加了成本，还可能引入自我偏袒</strong>。正确说法是「Reflection 是校验失败时的重试机制，它的价值取决于回灌进去的那条具体报错」。</li><li><strong>术语只有中文没有英文原词</strong>。面试官和技术面试官的检索词是 ReAct、Function Calling、JSON Schema、CoT、Self-Consistency、Context Engineering、Prompt Caching、Prompt Injection。<strong>说中文没问题，但要能接住英文提问</strong>——这一条不影响深度，但影响你能不能听懂问题。</li></ol><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>上一层：<a href="/learn/kb/l1-llm/">L1 · 大模型基础</a>（tokenizer、注意力、采样参数——本层所有「数量级」判断都从那里来）</li><li>更底层：<a href="/learn/kb/l0-foundation/">L0 · 编程与工程基础</a>（Python 类型与数据校验、配置管理——本层第 5 页的所有校验代码都建立在这两页上）</li><li>面试：<a href="/learn/interview/cheatsheet.html">面试速查表</a></li><li>图库：<a href="/learn/diagrams/">/diagrams/</a></li><li>项目：<a href="/learn/projects/yyhelp/">YYHelp 客服 Agent</a> ｜ <a href="/learn/projects/rag/">科研文献 RAG</a></li></ul>',24)])])}const m=d(n,[["render",a]]);export{p as __pageData,m as default};
